import { notFound } from "next/navigation";

import { VendorParticipationAction } from "@/components/portal";
import { Badge, Card } from "@/components/ui";
import { requireAuthenticatedUser } from "@/lib/auth";
import { getVendorAuctionView } from "@/services/vendor-participation";

export default async function VendorAuctionDetailsPage({ params }: { params: Promise<{ auctionId: string }> }) {
  const { auctionId } = await params; const view = await getVendorAuctionView(await requireAuthenticatedUser(), auctionId); if (!view) notFound(); const { auction, eligibility } = view;
  return <section className="mx-auto max-w-5xl space-y-6"><Card><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-sm text-[var(--color-text-muted)]">{auction.auctionNumber}</p><h1 className="mt-1 text-2xl font-semibold">{auction.title}</h1></div><Badge variant="success">{auction.type}</Badge></div>{auction.description ? <p className="mt-4 text-sm text-[var(--color-text-muted)]">{auction.description}</p> : null}<VendorParticipationAction allowed={eligibility.allowed} auctionId={auction.id} reason={eligibility.reason} /></Card><Card><h2 className="text-lg font-semibold">Participation</h2><p className="mt-3 text-sm">{auction.emdRequired ? `EMD required: ${auction.emdAmount?.toString() ?? "Amount pending"} ${auction.emdCurrency ?? auction.currency}. Verification will be available in a future step.` : "No EMD is required."}</p><p className="mt-2 text-sm text-[var(--color-text-muted)]">Scheduled {auction.scheduledStartAt.toLocaleString()} to {auction.scheduledEndAt.toLocaleString()}</p></Card><Card><h2 className="text-lg font-semibold">Lots</h2><div className="mt-4 space-y-3">{auction.items.map((item) => <div className="border-t border-[var(--color-border)] pt-3" key={item.id}><p className="font-medium">{item.lotNumber}. {item.name}</p><p className="mt-1 text-sm text-[var(--color-text-muted)]">{item.quantity.toString()} {item.unit}</p></div>)}</div></Card>{auction.documents.length || auction.media.length ? <Card><h2 className="text-lg font-semibold">Public files</h2><div className="mt-3 space-y-2">{auction.documents.map((file) => <a className="block text-sm text-[var(--color-primary)] hover:underline" href={`/api/auctions/${auction.id}/files/document/${file.id}`} key={file.id}>{file.fileName ?? file.name}</a>)}{auction.media.map((file) => <a className="block text-sm text-[var(--color-primary)] hover:underline" href={`/api/auctions/${auction.id}/files/media/${file.id}`} key={file.id}>{file.fileName ?? file.type}</a>)}</div></Card> : null}</section>;
}
